   Q("Calcula 1/4 + 3/8.", "5/8", "4/12", "4/8", "1/4 es 2/8, y 2/8 + 3/8 = 5/8."),
   Q("{F} ¿Cuánta pintura hay entre los dos recipientes?", "5/6 de litro", "3/9 de litro", "3/6 de litro", "2/3 es 4/6, y 4/6 + 1/6 = 5/6."),
