   Q("{F} ¿Cuántos kilos pesan juntas las manzanas y las paltas?", D(fr('1.35')+fr('0.8')), "1,43", "1,16", "Se escribe 0,80 para alinear: 1,35 + 0,80 = 2,15."),
   Q("{F} ¿Cuántos kilos más pesan los limones que las manzanas?", D(fr('2.05')-fr('1.35')), "1,3", "1,7", "2,05 − 1,35 se resta por lugares y da 0,70, o sea 0,7."),
